insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','スタジオでの演奏を、緊密なフレーミング、多重像、制御された照明によって再構成した作品。','ポップ映像がテレビ出演の記録と強く結びついていた時代に、目的を持って制作されたプロモーション映像の持続的なモデルを示しました。','Bruce Gowersの監督により1975年に制作され、Queenが各地のテレビ番組へ毎回出演せずとも、楽曲の統一された視覚的パフォーマンスを届ける役割を果たしました。','限定的な撮影環境を、象徴的な構図、顔の多重像、照明変化、楽曲のセクションに同期した編集によって強い視覚言語へ変換しています。','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='queen-bohemian-rhapsody' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A studio performance is reorganized through close framing, layered imagery, and controlled lighting.','The film established a durable model for the purpose-made promotional video while filmed pop performances were still closely tied to television appearances.','Made in 1975 under director Bruce Gowers, the film enabled Queen to circulate a consistent visual performance without appearing live on every television program.','A limited production setup is transformed by iconic composition, multi-layered faces, lighting changes, and edits synchronized to the song''s sectional structure.','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='queen-bohemian-rhapsody' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
