insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','分割画面、カメラへの直接的な視線、組み合わせの変化によって、簡素なスタジオ演奏をグループ像の精密な研究へ変換した作品。','反復可能なグラフィック手法だけで、物語的なロケーションや大規模な見世物に頼らず、人物性、リズム、恋愛的な含意を構成できることを示しました。','Lasse Hallströmの監督により1978年に公開され、国際流通のために専用プロモーション映像を継続制作したABBAの実践に位置づけられます。','4分割画面が各メンバーを分離し、再び組み合わせることで、楽曲の掛け合い構造を編集とフレーミングによって可視化しています。','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='abba-take-a-chance-on-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Split screens, direct address, and shifting pairings turn a studio performance into a controlled study of group identity.','The film shows how a repeatable graphic device can organize personality, rhythm, and romantic suggestion without narrative locations or spectacle.','Released in 1978 and directed by Lasse Hallström, the film belongs to ABBA''s sustained use of purpose-made promotional films for international circulation.','A four-way split screen separates and recombines the performers, making editing and framing carry the song''s call-and-response structure.','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='abba-take-a-chance-on-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
