insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','演奏、モノクロの放送イメージ、合成的な未来像を組み合わせ、メディアの変化を短い視覚的声明として提示した作品。','後にMTV最初の放送作品となったことで、プロモーション・フィルムの時代と音楽専門テレビの連続放送を隔てる象徴的な指標になりました。','Russell Mulcahyの監督により1979年に公開され、MTV開局以前に制作されながら、1981年の同局開局と切り離せない作品となりました。','高速編集、像の重なり、ネオン色、過去と未来の切り替えによって、楽曲が扱うメディア論を時間的な視覚構造へ変換しています。','Acquisition reason: Representative work for MTV Prelude.','verified',now() from public.works where slug='the-buggles-video-killed-the-radio-star' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Performance, monochrome broadcast imagery, and a synthetic future are combined in a compact statement about changing media.','Its later position as the first video broadcast by MTV made the film a marker between the promotional-film era and continuous music television.','Released in 1979 and directed by Russell Mulcahy, the film preceded MTV but became inseparable from the channel''s 1981 launch.','Rapid editing, image layering, neon color, and transitions between past and future turn the song''s media commentary into a visible temporal structure.','Acquisition reason: Representative work for MTV Prelude.','verified',now() from public.works where slug='the-buggles-video-killed-the-radio-star' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
