insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','テムズ川沿いの桟橋で演奏するバンドを、雨、暗闇、不安定な撮影条件そのものを主要な空気として捉えた作品。','困難なロケーション撮影の偶発性を、パンクの直接性と楽曲の警告的な感覚に一致する視覚言語へ変換しています。','Don Lettsの監督により1979年に制作され、テムズ川のBatterseaで撮影された本作は、The Clashを代表する映像のひとつとなりました。','自然の天候、限定的な照明、複数のカメラ位置、強い演奏を、制作上の欠点ではなく構造的な資産として扱っています。','Acquisition reason: Representative work for Punk.','verified',now() from public.works where slug='the-clash-london-calling' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The band performs on a Thames-side pier as rain, darkness, and unstable conditions become the video''s principal atmosphere.','The film turns the contingency of a difficult location shoot into a visual language consistent with punk''s directness and the song''s sense of warning.','Directed by Don Letts in 1979, the film was shot at Battersea on the River Thames and became one of The Clash''s defining moving images.','Available weather, limited lighting, multiple camera positions, and forceful performance are treated as structural assets rather than production defects.','Acquisition reason: Representative work for Punk.','verified',now() from public.works where slug='the-clash-london-calling' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
