insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','ソラリゼーションされた場面が、ピエロ、制度的な人物像、工業的な海岸をひとつの不安定な視覚世界に配置する作品。','美術、衣装、画像処理、象徴的な演技を、楽曲を飾る要素ではなくポップ・アイデンティティを構成する同等の要素として扱っています。','David BowieとDavid Malletの共同監督により1980年に公開され、Bowieの過去の人物像をビデオ時代の新たに統御されたイメージとして提示しました。','ソラリゼーション、限定色、演出された行列、急激なスケール変化によって、連続的な物語ではなく反復から成立する視覚構造を作っています。','Acquisition reason: Representative work for Art Direction.','verified',now() from public.works where slug='david-bowie-ashes-to-ashes' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Solarized tableaux place Pierrot, institutional figures, and an industrial shoreline within one unstable visual world.','The film treats art direction, costume, image processing, and symbolic performance as equal components of a pop identity.','Released in 1980 and co-directed by David Bowie and David Mallet, the film revisits Bowie''s earlier characters through a newly controlled video-era image.','Solarization, restricted color, staged procession, and abrupt changes of scale create a structure that operates through recurrence rather than continuous narrative.','Acquisition reason: Representative work for Art Direction.','verified',now() from public.works where slug='david-bowie-ashes-to-ashes' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
