insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','機械仕掛けのマネキン、家庭用品、断片化された身体が作り込まれた室内で動き、Hancock本人は離れたテレビ画面の中にだけ現れる作品。','通常のアーティスト演奏から自律した美術空間へ視線を移し、実験的な電子音楽を音楽テレビの広い視聴層へ運びました。','Godley & Cremeの監督により1983年に公開され、MTVが黒人アーティストへ与える可視性が限定的だった時期に、Jim Whitingの動く彫刻を中心に制作されました。','彫刻的な機構、時間制御された物理運動、急なフレーミング、画面内画面によって、セットそのものを主要な演者へ変えています。','Acquisition reason: Representative work for Robotics.','verified',now() from public.works where slug='herbie-hancock-rockit' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Mechanical mannequins, domestic objects, and fragmented body parts perform inside a constructed apartment while Hancock appears at a distance on a television screen.','The film redirected attention from conventional artist performance toward an autonomous designed environment while carrying an experimental electronic track into heavy music-television rotation.','Released in 1983 and directed by Godley & Creme, the video was built around Jim Whiting''s moving sculptures during a period when MTV gave little visibility to Black artists outside a narrow pop format.','Sculptural mechanisms, timed physical motion, abrupt framing, and screen-within-screen presentation turn the set itself into the principal performer.','Acquisition reason: Representative work for Robotics.','verified',now() from public.works where slug='herbie-hancock-rockit' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
