insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','ドラマ的な物語、振付、特殊メイク、特殊効果を組み合わせた長編形式のミュージックビデオ。','ミュージックビデオを映画的な長編ストーリーテリングへ拡張した代表的作品です。','1983年に公開され、35mmフィルムによる劇場上映も行われました。2009年には米国国立フィルム登録簿に選定されています。','物語演出、振付、特殊メイク、特殊効果を長編形式のミュージックビデオへ統合しています。','Acquisition reason: Representative work for Narrative Revolution.','verified',now() from public.works where slug='michael-jackson-thriller' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A long-form music video combining dramatic narrative, choreography, make-up, and special effects.','Thriller is a landmark example of the music video expanding into cinematic, long-form storytelling.','Released in 1983, the film was also shown theatrically in 35mm and was selected for the U.S. National Film Registry in 2009.','It integrates narrative filmmaking, choreography, make-up, and special effects within an extended music-video format.','Acquisition reason: Representative work for Narrative Revolution.','verified',now() from public.works where slug='michael-jackson-thriller' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
