insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','未実現の長編映画企画を、儀式、機械、拘束、見世物が密集する大規模な終末後のセットへ転換した作品。','MV制作が、長編映画に近い美術的野心、予算、世界構築を吸収し得た時点を示しています。','Russell Mulcahyの監督により1984年に公開され、William S. Burroughs『The Wild Boys』の未実現映画化企画で開発された構想を再利用し、Shepperton Studiosで10日間にわたり撮影されました。','巨大セット、機械装置、水、火、衣装、集団演技を、個別の効果の寄せ集めではなく、連続するひとつの構築世界として統御しています。','Acquisition reason: Representative work for Production Design.','verified',now() from public.works where slug='duran-duran-the-wild-boys' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A large-scale post-apocalyptic set turns unrealized feature-film development into a dense sequence of ritual, machinery, confinement, and spectacle.','The film demonstrates the point at which a music-video production could absorb the design ambition, budget, and world-building associated with a feature project.','Released in 1984 and directed by Russell Mulcahy, the video reused concepts developed for an unrealized adaptation of William S. Burroughs'' The Wild Boys and was filmed over ten days at Shepperton Studios.','Monumental sets, mechanical rigs, water, fire, costume, and mass performance are coordinated as a continuous constructed world rather than a sequence of unrelated visual effects.','Acquisition reason: Representative work for Production Design.','verified',now() from public.works where slug='duran-duran-the-wild-boys' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
