insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','実写のロマンスが、ロトスコープによる鉛筆画の世界へと横断していくミュージックビデオ。','アニメーションと実写を、ひとつの連続した物語空間として成立させた代表的作品です。','広く知られる1985年版はSteve Barronが監督し、楽曲の国際的なビジュアルイメージを決定づけました。','フレーム単位のロトスコープ表現によって、撮影映像とイラストレーションを分断せずに接続しています。','Acquisition reason: Representative work for Animation.','verified',now() from public.works where slug='a-ha-take-on-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A live-action romance crosses into a pencil-drawn world through rotoscope animation.','Take On Me remains a defining example of animation and live action functioning as one continuous narrative space.','The widely recognized 1985 video was directed by Steve Barron and became central to the song''s international visual identity.','Frame-by-frame rotoscope animation connects filmed performance and illustration without separating them into independent sections.','Acquisition reason: Representative work for Animation.','verified',now() from public.works where slug='a-ha-take-on-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
