insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','コンピューター生成の労働者、家電、グラフィック面を演奏映像と交差させ、音楽テレビ自体へ向けられた楽曲を可視化した作品。','初期のキャラクター型コンピューター映像を大規模なテレビ視聴者へ提示し、同時にその放送メディア自体を作品の主題へ取り込みました。','Steve Barronの監督により1985年に公開され、Dire Straitsの『Brothers in Arms』期を代表し、MTVの国際展開と強く結びつく映像となりました。','ブロック状の3D人物、仮想環境、デジタルで造形された物体を、短い効果ではなく映像全体を支える前提として実写演奏と統合しています。','Acquisition reason: Representative work for Early CGI.','verified',now() from public.works where slug='dire-straits-money-for-nothing' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Computer-generated workers, appliances, and graphic surfaces are intercut with performance footage to visualize a song already addressed to music television.','The film made early character-based computer imagery visible to a mass television audience while using the medium itself as part of the subject.','Released in 1985 and directed by Steve Barron, the video accompanied Dire Straits'' Brothers in Arms period and became closely associated with MTV''s international expansion.','Block-like three-dimensional figures, simulated environments, and digitally modeled objects are integrated with live performance as a sustained visual premise rather than a brief effect.','Acquisition reason: Representative work for Early CGI.','verified',now() from public.works where slug='dire-straits-money-for-nothing' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
