insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','『Diamonds Are a Girl''s Best Friend』の舞台的再構成を、演技、求愛、富のイメージをめぐるもうひとつの物語で包んだ作品。','すでに認知されたハリウッド映画の場面を、引用、スター像の構築、公的な人格とそれを見つめる人物の距離を考える映像へ変換しました。','Mary Lambertが監督し、1985年にMTVで広く放送され、Madonnaの公的イメージに結びつく「Material Girl」という人格形成の中心となりました。','精密な映画引用をバックステージの枠物語へ組み込み、振付、衣装、色彩、観客の視線によって、再現されるイメージ自体を批評する構造を作っています。','Acquisition reason: Representative work for Hollywood.','verified',now() from public.works where slug='madonna-material-girl' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A staged reconstruction of Diamonds Are a Girl''s Best Friend is framed by a second narrative about performance, courtship, and the image of wealth.','The film turns an already recognizable Hollywood sequence into a study of quotation, star construction, and the distance between a public persona and the character observing it.','Directed by Mary Lambert, the video entered heavy MTV circulation in 1985 and became central to the Material Girl persona attached to Madonna''s public image.','The video places a precise cinematic quotation inside a backstage frame story, allowing choreography, costume, color, and spectatorship to comment on the image being reproduced.','Acquisition reason: Representative work for Hollywood.','verified',now() from public.works where slug='madonna-material-girl' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
