insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','『Spitting Image』の人形が、バンドと冷戦期の政治家たちをRonald Reaganの拡大していく悪夢の中へ配置する作品。','既存のテレビ風刺の言語を用い、政治的カリカチュア、著名人文化、バンド演奏を同じ物語システムの中に共存させました。','John LloydとJim Yukichの監督により1986年に公開され、冷戦最後の10年間に『Spitting Image』の視覚世界をMV形式へ移植しました。','専用制作の人形、声の演技、ミニチュア的な舞台、政治家と大衆文化の人物を横断する急速な切替によって、一度の視覚的な冗談ではなく楽曲全体に風刺を持続させています。','Acquisition reason: Representative work for Puppetry.','verified',now() from public.works where slug='genesis-land-of-confusion' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Spitting Image puppets place the band and Cold War political figures inside Ronald Reagan''s escalating nightmare.','The film uses an established television satire language to make political caricature, celebrity culture, and band performance occupy the same narrative system.','Released in 1986 and directed by John Lloyd and Jim Yukich, the video adapted the visual world of Spitting Image to a music-video format during the final decade of the Cold War.','Purpose-built puppets, vocal performance, miniature staging, and rapid shifts between political and popular figures sustain satire across an entire song rather than a single visual joke.','Acquisition reason: Representative work for Puppetry.','verified',now() from public.works where slug='genesis-land-of-confusion' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
