insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','ストップモーション、ピクシレーション、クレイアニメーション、実写の演技によって、歌い手の身体を連続する物理的変形として再構成した作品。','フレーム単位のアニメーションを、人物やリズムから切り離すことなく、メインストリームのMVパフォーマンスの中心へ置きました。','1986年に公開され、Stephen R. Johnson、Aardman Animation、Nick Park、Brothers Quay、Peter Lord、Richard Goleszowskiらがひとつの共同制作に参加しました。','演者の身体と周囲の空間を直接アニメートし、物体、表情、照明、置換効果をひとつの振付された映像システムとして機能させています。','Acquisition reason: Representative work for Stop Motion.','verified',now() from public.works where slug='peter-gabriel-sledgehammer' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Stop-motion, pixilation, clay animation, and live-action performance reorganize the singer''s body through a continuous sequence of physical transformations.','The film places frame-by-frame animation at the center of a mainstream music-video performance without separating technique from character or rhythm.','Released in 1986, the video brought together Stephen R. Johnson, Aardman Animation, Nick Park, the Brothers Quay, Peter Lord, and Richard Goleszowski within one collaborative production.','Animation is performed on and around the artist, allowing objects, facial movement, lighting, and replacement effects to operate as a single choreographed image system.','Acquisition reason: Representative work for Stop Motion.','verified',now() from public.works where slug='peter-gabriel-sledgehammer' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
