insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','目撃された犯罪、宗教的な場面、パフォーマンス、演劇的な種明かしを、道徳と象徴が衝突する連続として構成した作品。','物語、宗教的イメージ、人種、社会的論争を装飾的な記号へ還元せず、メインストリームのMV内で同時に扱えることを示しました。','Mary Lambertの監督により1989年に公開され、燃える十字架、聖痕、聖人像、Pepsiによるキャンペーン支援撤回をめぐる議論と切り離せない作品となりました。','現実に見える場面、宗教的図像、舞台空間、カーテンコールによる開示を往復し、観客が見た出来事の意味を演劇的な構造で複雑化しています。','Acquisition reason: Representative work for Cultural Impact.','verified',now() from public.works where slug='madonna-like-a-prayer' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A witnessed crime, religious tableaux, performance, and theatrical revelation are organized as a sequence of moral and symbolic confrontations.','The film demonstrates how a mainstream music video could combine narrative, religious imagery, race, and public controversy without reducing them to decorative motifs.','Released in 1989 and directed by Mary Lambert, the video became inseparable from debates around its burning crosses, stigmata, saint figure, and the withdrawal of Pepsi''s campaign support.','The video moves between apparent reality, devotional iconography, stage space, and curtain-call disclosure, using theatrical structure to complicate what the viewer has witnessed.','Acquisition reason: Representative work for Cultural Impact.','verified',now() from public.works where slug='madonna-like-a-prayer' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
