insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','コンサート演奏、結婚の儀式、私的な親密さ、葬儀のイメージによって、ロックバラードを大規模なメロドラマ的物語へ拡張した作品。','楽曲の長さを用いて見世物と解決されない物語断片を持続させ、1990年代初頭のロックMV制作が到達した規模を示しました。','Andy Morahanの監督により1992年に公開され、『Use Your Illusion』期に制作された、バンドの連続する大規模物語映像群の一部です。','複数の場所、空撮的な規模、ライブ演奏、気象効果、時間の急な転換を因果関係の完全な説明なしに組み合わせ、モンタージュによって感情の連続性を維持しています。','Acquisition reason: Representative work for Epic.','verified',now() from public.works where slug='guns-n-roses-november-rain' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Concert performance, wedding ritual, domestic intimacy, and funeral imagery expand a rock ballad into a large-scale melodramatic narrative.','The film demonstrates the peak scale of early-1990s rock-video production, using the duration of the song to sustain spectacle and unresolved narrative fragments.','Released in 1992 and directed by Andy Morahan, the video belongs to the Use Your Illusion period and forms part of the band''s connected cycle of expansive narrative videos.','Multiple locations, aerial scale, live performance, weather effects, and abrupt shifts in time are assembled without fully explaining causality, allowing montage to carry emotional continuity.','Acquisition reason: Representative work for Epic.','verified',now() from public.works where slug='guns-n-roses-november-rain' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
