insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','BjörkがNew Yorkを走るトラックの荷台で、セットに隔離されることなく、白黒映像の中で踊り歌う作品。','ひとつの移動する演技だけで成立させ、危険、交通、変化する背景、カメラとの直接的な関係からエネルギーを引き出しました。','Stéphane Sednaouiの監督により1993年の『Debut』期に公開され、最小限のパフォーマンス映像の中で都市を能動的な共演者として提示しました。','移動する足場、正面構図、途切れない都市の変化、即興的な身体反応によって、物語構築を持続する存在感へ置き換えています。','Acquisition reason: Candidate representative work for Performance.','verified',now() from public.works where slug='bjork-big-time-sensuality' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Björk dances and sings in black and white on the bed of a truck moving through New York, exposed to the city rather than isolated on a set.','The video makes a single mobile performance sufficient, deriving energy from risk, traffic, changing background, and the artist''s direct relation to the camera.','Released in 1993 during the Debut period and directed by Stéphane Sednaoui, the work presented the city as an active partner in an otherwise minimal performance film.','A moving platform, frontal framing, uninterrupted urban variation, and spontaneous bodily response replace narrative construction with sustained presence.','Acquisition reason: Candidate representative work for Performance.','verified',now() from public.works where slug='bjork-big-time-sensuality' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
