insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','バンド自身が架空の俳優を演じ、追跡、タイトル、スタント、静止画による人物紹介を備えた1970年代刑事テレビの圧縮されたパロディを構成する作品。','パロディと演奏を不可分にし、既存ジャンルを参照するだけでなく、架空のテレビ番組そのものをMVとして作れることを示しました。','Spike Jonzeの監督により1994年の『Ill Communication』期に公開され、洗練されたスタジオ型スペクタクルに対する、低予算で監督主導の1990年代的選択肢を代表しました。','手持ちアクション、急なズーム、断続的な編集、人物カード、誇張された演技によって、架空テレビシリーズの文法を楽曲の長さへ再構成しています。','Acquisition reason: Representative work for Parody.','verified',now() from public.works where slug='beastie-boys-sabotage' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The band performs fictional actors inside a compressed parody of 1970s police television, complete with chases, titles, stunts, and freeze-frame characterization.','The film made parody inseparable from performance, showing that a music video could construct a complete fictional television object rather than merely reference a genre.','Released with Ill Communication in 1994 and directed by Spike Jonze, the video became a central example of the decade''s low-budget, director-led alternative to polished studio spectacle.','Handheld action, crash zooms, discontinuous cutting, character cards, and deliberately excessive acting reproduce the grammar of an imagined television series at song length.','Acquisition reason: Representative work for Parody.','verified',now() from public.works where slug='beastie-boys-sabotage' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
