insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','解剖標本、機械装置、宗教的象徴、動物、吊られたTrent Reznorの演技を、損傷した実験室のタブローとして連ねる作品。','検閲を作品内部で可視化し、欠損した放送映像を単なる流通上の問題ではなく、作品の歴史的形態の一部として扱いました。','Mark Romanekの監督により1994年に制作され、編集された放送版が流通する一方、無修正版はホームビデオや後年の公式公開と結びつきました。','手作業で処理されたフィルム質感、『scene missing』と記された断続フレーム、機械的反復、美術館的なタブローによって、アーカイブの劣化と精密な美術を融合しています。','Acquisition reason: Representative work for Industrial.','verified',now() from public.works where slug='nine-inch-nails-closer' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A sequence of distressed laboratory tableaux combines anatomical specimens, mechanical devices, religious symbols, animals, and Trent Reznor''s suspended performance.','The video made censorship visible within the work itself and treated the damaged broadcast image as part of its historical form rather than a neutral delivery problem.','Directed by Mark Romanek in 1994, the work circulated in edited broadcast versions while its uncensored form remained tied to home-video and later official releases.','Hand-processed film texture, intermittent frames marked ''scene missing,'' mechanical repetition, and museum-like tableaux fuse archival decay with controlled art direction.','Acquisition reason: Representative work for Industrial.','verified',now() from public.works where slug='nine-inch-nails-closer' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
