insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','固定された笑顔と歪んだ顔を持つ郊外の風景が終末的な空へ飲み込まれ、バンドも同じ不安定な世界の中で演奏する作品。','グランジ期の不安を、記録的な真正性ではなくグロテスクな変形によって、広く読める郊外の悪夢へ変えました。','Howard Greenhalghの監督により1994年に公開され、Soundgardenの『Superunknown』期を代表する視覚的な対作品となりました。','顔のワープ、色彩を強調した合成、誇張された演技、ミニチュアのような郊外、すべてを飲み込む空によって、陽気な日常表面から恐怖を構築しています。','Acquisition reason: Representative work for Surrealism.','verified',now() from public.works where slug='soundgarden-black-hole-sun' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A suburban landscape of fixed smiles and distorted faces gives way to an apocalyptic sky while the band performs inside the same unstable world.','The video converted grunge-era unease into a broadly legible suburban nightmare, using grotesque transformation rather than documentary authenticity.','Released in 1994 and directed by Howard Greenhalgh, the video became a prominent visual counterpart to Soundgarden''s Superunknown period.','Facial warping, chromatic compositing, exaggerated performance, miniature-like suburbia, and a consuming sky build horror out of cheerful everyday surfaces.','Acquisition reason: Representative work for Surrealism.','verified',now() from public.works where slug='soundgarden-black-hole-sun' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
