insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','移動して見える部屋、振付、実践的な空間トリックを軸に構成されたパフォーマンス映像。','抑制されたセットと精密なパフォーマンスから、忘れがたい映像的アイデアを生み出した基準点です。','1996年に公開され、Jonathan Glazerが監督した本作は、1990年代を象徴するMVイメージのひとつとなりました。','セットの移動、カメラのフレーミング、振付、物体の動きを同期させ、不安定に変化する部屋の錯覚を作っています。','Acquisition reason: Representative work for Set Design.','verified',now() from public.works where slug='jamiroquai-virtual-insanity' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A performance video built around an apparently shifting room, choreographed movement, and practical spatial illusion.','Virtual Insanity is a benchmark for creating an unforgettable visual premise from a restrained set and tightly controlled performance.','Released in 1996 and directed by Jonathan Glazer, the video became one of the defining music-video images of the decade.','Coordinated set movement, camera framing, choreography, and selective object motion create the illusion of an unstable room.','Acquisition reason: Representative work for Set Design.','verified',now() from public.works where slug='jamiroquai-virtual-insanity' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
