insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','アーティストの顔を持つ子どもたちが集合住宅地を群れで走り、テレビから現れる怪物を囲み、その叫びが老女を圧倒する作品。','ボディホラー、社会写実的なロケーション、電子音楽の人格をひとつの映像システムへ統合し、それぞれの対立性を弱めませんでした。','Chris Cunninghamの監督によりWarpから1997年に公開され、電子音楽と物質感の強いデジタル時代の恐怖表現を結ぶ継続的な文脈を確立しました。','顔の置換、特殊造形、ドキュメンタリー調の撮影、急速な運動、至近距離で持続する叫びによって、日常と人工物を結合しています。','Acquisition reason: Representative work for Experimental.','verified',now() from public.works where slug='aphex-twin-come-to-daddy' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Children bearing the artist''s face swarm a housing estate and gather around a television-born creature whose scream overwhelms an elderly witness.','The film brought body horror, social-realist location work, and electronic-music identity into a single image system without softening their antagonism.','Released by Warp in 1997 and directed by Chris Cunningham, the video established a recurring collaboration between electronic music and a distinctly physical form of digital-era horror.','Face replacement, prosthetic character design, documentary-textured photography, rapid movement, and an extended close-range scream combine the familiar and synthetic.','Acquisition reason: Representative work for Experimental.','verified',now() from public.works where slug='aphex-twin-come-to-daddy' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
