insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','衣装をまとった複数のパフォーマーが、楽曲の各パートを精密な振付システムへ翻訳する作品。','楽曲構造そのものを、MVの物語と構成原理へ変換できることを示した作品です。','1997年に公開され、Michel Gondryが監督した本作は、1990年代後半の監督主導型MV文化を代表しています。','異なるパフォーマー群が別々の音楽要素を担当し、反復とアレンジを視覚的な振付として可視化しています。','Acquisition reason: Representative work for Choreography.','verified',now() from public.works where slug='daft-punk-around-the-world' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Costumed performers translate separate parts of the track into a precisely organized choreographic system.','Around the World demonstrates how musical structure itself can become the narrative and organizing principle of a music video.','Released in 1997 and directed by Michel Gondry, the video belongs to the director-driven music-video culture of the late 1990s.','Distinct performer groups embody different musical components, turning repetition and arrangement into visible choreography.','Acquisition reason: Representative work for Choreography.','verified',now() from public.works where slug='daft-punk-around-the-world' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
