insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','眠る男女が入れ子状の悪夢を通過し、変形した身体、家庭空間、バンド演奏が絶えず役割を交換する作品。','夢の論理を物理的な演出へ翻訳し、説明的な接続を必要とせず、縮尺、人格、ジャンルを変化させました。','Michel Gondryの監督により1997年に公開され、バンドの演奏をホラーと家庭的な夢の連鎖の中へ配置しています。','巨大な実物の手、強制遠近、衣装による変身、リアプロジェクション、循環する覚醒の移行によって、夢の連続性を触覚的な効果で再現しています。','Acquisition reason: Representative work for Dream.','verified',now() from public.works where slug='foo-fighters-everlong' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A sleeping couple moves through nested nightmares in which distorted bodies, domestic space, and band performance continually exchange roles.','The film translates dream logic into physical staging, allowing scale, identity, and genre to change without requiring explanatory transitions.','Released in 1997 and directed by Michel Gondry, the video places the band''s performance inside a succession of horror and domestic dream scenarios.','Oversized practical hands, forced scale, costume transformation, rear projection, and circular waking transitions reproduce the continuity of a dream through tactile effects.','Acquisition reason: Representative work for Dream.','verified',now() from public.works where slug='foo-fighters-everlong' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
