insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Missy Elliottが雨、反射面、魚眼の歪み、ダンサー、身体の輪郭を大きく変える黒い膨張スーツの中で演じる作品。','女性ラップの演技イメージを、既存の提示慣習ではなく、縮尺、ユーモア、身体の主体性、未来性に基づいて確立しました。','1997年に公開され、ElliottとHype Williamsの最初の協働となり、デビューアルバムを取り巻く視覚言語を提示しました。','極端な広角光学、カメラへの直接的な演技、彫刻的なスタイリング、誇張された奥行きによって、アーティストの身体を画面構造の起点にしています。','Acquisition reason: Representative work for Fashion.','verified',now() from public.works where slug='missy-elliott-the-rain-supa-dupa-fly' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Missy Elliott performs through rain, reflective surfaces, fisheye distortion, dancers, and an inflated black suit that radically changes her silhouette.','The video established an image of female rap performance grounded in scale, humor, bodily autonomy, and futurism rather than inherited conventions of presentation.','Released in 1997, it was the first collaboration between Elliott and Hype Williams and introduced the visual language surrounding her debut album.','Extreme wide-angle optics, direct-to-camera performance, sculptural styling, and exaggerated spatial depth make the artist''s body the source of the frame''s visual logic.','Acquisition reason: Representative work for Fashion.','verified',now() from public.works where slug='missy-elliott-the-rain-supa-dupa-fly' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
