insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','暗い道路で車が走る男を追い、Thom Yorkeが後部座席から見つめるなか、炎によって追跡の関係が反転する作品。','ひとつの空間的前提だけで不安を持続させ、説明を保留し、カメラの位置によって観客を追跡へ巻き込みました。','1997年の『OK Computer』期に公開され、Jonathan Glazerが監督し、Academy Filmsを通じて制作されました。','限定された照明、長い追跡撮影、画面外の脅威、追う者と追われる者の反転によって、単純な道路を完結した物語装置へ変えています。','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='radiohead-karma-police' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A car follows a running man along an unlit road while Thom Yorke watches from the rear seat, until the pursuit reverses through fire.','The film sustains dread with one spatial premise, withholding explanation and using the camera''s position to implicate the viewer in the pursuit.','Released in 1997 during the OK Computer period, the video was directed by Jonathan Glazer and produced through Academy Films.','Restricted illumination, long-duration tracking, off-screen threat, and a reversal of pursuer and pursued turn a simple road into a complete narrative mechanism.','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='radiohead-karma-police' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
