insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','酩酊、暴力、盗難、性行為に至る一夜を、正体が伏せられた人物の一人称視点でほぼ全編描く作品。','POVを短い効果ではなく倫理的・知覚的な罠として用い、最後の正体開示まで観客に行為者の位置を占めさせました。','Jonas Åkerlundが監督し1997年に公開され、放送制限、暴力、性表現、MV検閲をめぐる議論と切り離せない作品となりました。','身体に取り付けた主観カメラ、酩酊状態の動き、隠された人物像、遅れて現れる鏡の開示によって、視点自体を物語構造へ変えています。','Acquisition reason: Representative work for POV.','verified',now() from public.works where slug='the-prodigy-smack-my-bitch-up' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A night of intoxication, violence, theft, and sex is presented almost entirely through the first-person viewpoint of an initially unidentified protagonist.','The film uses point of view not as a brief effect but as an ethical and perceptual trap, forcing the viewer to occupy behavior before the final identity reveal.','Directed by Jonas Åkerlund and released in 1997, the video became inseparable from debates about broadcast restriction, violence, sexuality, and music-video censorship.','A body-mounted subjective camera, altered-state movement, concealed identity, and a delayed mirror reveal make viewpoint itself the narrative structure.','Acquisition reason: Representative work for POV.','verified',now() from public.works where slug='the-prodigy-smack-my-bitch-up' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
