insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Madonnaが砂漠でひとり演じ、身体が分裂し、地面へ折り畳まれ、鳥や黒い犬へ変身する作品。','特殊効果によって単独の演技を可変的な像へ拡張し、人間、動物、風景の形を横断しても人物の一貫性を保ちました。','Chris Cunninghamの監督により1998年に公開され、『Ray of Light』期の電子的な音響を禁欲的な砂漠のイメージへ結びました。','モーションコントロールによる反復、デジタル複製、モーフィング、シルエット、布の運動によって、変身を連続する振付として構成しています。','Acquisition reason: Representative work for Visual FX.','verified',now() from public.works where slug='madonna-frozen' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Madonna performs alone in a desert as her body divides, folds into the ground, and transforms into birds and a black dog.','The film uses effects to extend a single performance into a mutable figure whose identity remains coherent across human, animal, and landscape forms.','Released in 1998 and directed by Chris Cunningham, the work joined the Ray of Light period''s electronic sound to an austere desert image.','Motion-controlled repetition, digital duplication, morphing, silhouette, and fabric movement turn transformation into a continuous choreographic event.','Acquisition reason: Representative work for Visual FX.','verified',now() from public.works where slug='madonna-frozen' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
