insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','胎児が子宮内から歌うように現れ、抽象的な暗い空間の中で身体と顔の動きが楽曲へ同期する作品。','技術的に構築された胎内イメージを抑制された演技へ変え、スペクタクルではなく脆さに効果全体を支配させました。','Walter Sternの監督により1998年の『Mezzanine』期に公開され、Massive Attackと監督の協働を、デジタルで媒介された単一被写体の映像へ展開しました。','解剖学的参照、リップシンク、流動的な動作、制御された照明を統合したCG胎児の演技を、アーティスト映像へ切り替えず持続させています。','Acquisition reason: Representative work for Art.','verified',now() from public.works where slug='massive-attack-teardrop' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A fetus appears to sing from within the womb, its movements and facial articulation synchronized to the track inside an otherwise abstract dark space.','The film turns a technically constructed prenatal image into a restrained performance, allowing vulnerability rather than spectacle to govern the effect.','Released in 1998 during the Mezzanine period and directed by Walter Stern, the video extended Massive Attack''s collaboration with the director into a digitally mediated single-subject image.','A sustained computer-generated fetal performance combines anatomical reference, lip synchronization, fluid motion, and controlled lighting without cutting away to the artist.','Acquisition reason: Representative work for Art.','verified',now() from public.works where slug='massive-attack-teardrop' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
