insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','白い人型機械二体が、明るい臨床的な空間で組み立てられ、観察され、親密な接触へ導かれる作品。','ロボット技術を技術展示ではなく親密さと欲望の媒体として扱い、感情の曖昧さをVFX表現の中心に置きました。','Chris Cunninghamが監督し1999年に公開され、『Homogenic』最後のシングルに伴う映像として、美術館、デザイン賞、MV賞の文脈へ早くから入りました。','実写演技、人工外装、モーションコントロール撮影、デジタル合成を統合し、人間の顔の存在感と製造された身体の境界を解消しないまま接続しています。','Acquisition reason: Representative work for Robotics.','verified',now() from public.works where slug='bjork-all-is-full-of-love' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Two white humanoid machines are assembled, observed, and drawn into an intimate encounter inside a bright clinical environment.','The film treats robotics as a vehicle for tenderness and desire rather than technological display, making emotional ambiguity central to its effects work.','Directed by Chris Cunningham and released in 1999, the video accompanied the final single from Homogenic and entered museum, design, and music-video award contexts soon after release.','Live-action performance, prosthetic shells, motion-controlled photography, and digital compositing merge human facial presence with manufactured bodies without resolving the boundary between them.','Acquisition reason: Representative work for Robotics.','verified',now() from public.works where slug='bjork-all-is-full-of-love' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
