insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','擬人化された牛乳パックが家族の家を出て、行方不明のGraham Coxonを探しながら都市を旅し、危険と出会いを経験する作品。','使い捨ての容器に完結した感情の弧を与え、キャラクターデザインと抑制された演技だけで長編的なMV物語を支えられることを示しました。','1999年に公開され、Garth JenningsがHammer & Tongsを通じて監督し、Jim Hensonのワークショップに関連する造形技術が用いられました。','単純なパックの輪郭、実物のパペット、明確な身振り、ロケーション規模の演出によって、言葉を持たない商品容器を脆い主人公として読ませています。','Acquisition reason: Representative work for Character.','verified',now() from public.works where slug='blur-coffee-and-tv' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','An anthropomorphic milk carton leaves a family home to search the city for the missing Graham Coxon, encountering danger and companionship along the way.','The film gives a disposable package a complete emotional arc, showing how character design and restrained performance can carry a long-form music-video narrative.','Released in 1999, the video was directed by Garth Jennings through Hammer & Tongs, with creature work associated with Jim Henson''s workshop.','A simple carton silhouette, practical puppetry, legible gesture, and location-scale staging make a nonverbal branded object readable as a vulnerable protagonist.','Acquisition reason: Representative work for Character.','verified',now() from public.works where slug='blur-coffee-and-tv' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
