insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','小売店で働く女性が日常と万華鏡的な夢を往復し、身体と周囲の空間が実物の幾何学模様として反復する作品。','光学合成の論理をセット、振付、インカメラの移行で再構築し、デジタルに見える多重性を明確に物理的なまま保ちました。','Michel Gondryの監督により1999年、『Surrender』期に公開され、監督による音楽的反復の研究を継続する作品です。','回転セット、同期する複数の演者、マッチカット、鏡像的な隊形、機械的な転換によって、サイケデリックな重層を舞台上の演技へ翻訳しています。','Acquisition reason: Candidate representative work for Editing / Loop.','verified',now() from public.works where slug='chemical-brothers-let-forever-be' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A retail worker moves between waking routine and kaleidoscopic dream sequences in which her body and surroundings repeat as practical geometric patterns.','The video recreates the logic of optical compositing through sets, choreography, and in-camera transitions, allowing digital-looking multiplicity to remain visibly physical.','Released in 1999 and directed by Michel Gondry, the work belongs to the Chemical Brothers'' Surrender period and continues the director''s investigation of musical repetition.','Rotating sets, synchronized doubles, match cuts, mirrored formations, and mechanical transitions translate psychedelic layering into staged performance.','Acquisition reason: Candidate representative work for Editing / Loop.','verified',now() from public.works where slug='chemical-brothers-let-forever-be' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
