insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','バンドメンバーが操作可能なアバターとなり、シミュレートされたCaliforniaで別々のミッションを進み、ゲーム世界の崩壊から実演へ移行する作品。','当時の家庭用ゲームの視覚文法を装飾的な引用ではなく、完結した物語環境として扱いました。','Jonathan DaytonとValerie Farisの監督により2000年に公開され、3Dオープンワールドゲームのイメージが広く共有される視覚言語になりつつある時期に登場しました。','インターフェース、ミッション構造、アバターの動き、ゲーム的カメラ、ステージ遷移を統合し、架空のゲームをMVとして一貫して読めるものにしています。','Acquisition reason: Representative work for Game Aesthetic.','verified',now() from public.works where slug='red-hot-chili-peppers-californication' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The band members appear as playable avatars moving through separate missions in a simulated California before the game world collapses into live performance.','The video treats the visual grammar of a contemporary console game as a complete narrative environment rather than a decorative reference.','Released in 2000 and directed by Jonathan Dayton and Valerie Faris, the work arrived as three-dimensional open-world game imagery was becoming a widely shared visual language.','Interface graphics, mission logic, avatar movement, camera behavior, and level transitions are coordinated into a fictional game that remains legible as a music performance.','Acquisition reason: Representative work for Game Aesthetic.','verified',now() from public.works where slug='red-hot-chili-peppers-californication' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
