insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Christopher Walkenがホテルを一人で踊り進む、Spike Jonze監督のパフォーマンス映像。','一人の演者、身近なロケーション、明快な身体表現だけでMV全体を成立させた代表例です。','2001年に公開され、2002年のGRAMMY Best Music Videoを受賞。Spike Jonzeの代表作のひとつとなりました。','長回し、抑制されたVFX、振付、ワイヤーアクションによって、ホテル全体を連続した舞台へ変換しています。','Acquisition reason: Representative work for Dance.','verified',now() from public.works where slug='fatboy-slim-weapon-of-choice' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Christopher Walken dances alone through a hotel in a performance-led film directed by Spike Jonze.','The video shows how a single performer, a familiar location, and a clear physical premise can carry an entire music video.','Released in 2001, the video won the 2002 GRAMMY for Best Music Video and became one of Spike Jonze''s most widely recognized works.','Long takes, restrained visual effects, choreography, and wire-assisted movement turn an ordinary hotel into a continuous performance space.','Acquisition reason: Representative work for Dance.','verified',now() from public.works where slug='fatboy-slim-weapon-of-choice' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
