insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','宇多田ヒカルが、乗り物、トンネル、植物の形、ミニチュア世界、舞台機構が連なる鮮やかな人工の旅を進むポップ・ファンタジー。','美術設計を物語の運動として扱い、色、構築された空間、人工性を隠さない表現によって、移動を伸縮自在な想像環境の連続へ変えました。','楽曲は2001年に公開され、映像は2002年にDVDシングルとして発売。第17回日本ゴールドディスク大賞で邦楽部門（短編）のミュージック・ビデオ・オブ・ザ・イヤーを受賞しました。','ミニチュア、巨大な小道具、機械仕掛けの舞台、高彩度の色面、合成、急激なスケール変化によって、現実的な連続性に依存せず空間を次々と変形させています。','Acquisition reason: Representative work for Fantasy.','verified',now() from public.works where slug='hikaru-utada-traveling' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Utada moves through a brightly artificial journey of vehicles, tunnels, plant forms, miniature worlds, and stage machinery built as a continuous pop fantasy.','The video treats production design as narrative motion, using color, constructed space, and visible artifice to turn travel into an elastic sequence of imagined environments.','Released as a DVD single in 2002 after the song''s 2001 release, the work received the Japanese short-form Music Video of the Year award at the 17th Japan Gold Disc Awards.','Miniatures, oversized props, mechanical scenery, saturated color fields, compositing, and abrupt changes of scale allow each space to transform into the next without requiring realistic continuity.','Acquisition reason: Representative work for Fantasy.','verified',now() from public.works where slug='hikaru-utada-traveling' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
