insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','列車の窓から流れる建物、電柱、橋、ホームを、楽曲の反復する音の層に対応する可視的な要素へ変える作品。','図解や演奏場面を使わずに音楽構造を示し、日常的な風景を精密な視覚譜として機能させました。','Michel Gondryの監督により2002年に公開された作品です。編集上の正本では1990年代バッチに置かれていますが、年代メタデータは公式記録に従い2002年とします。','鉄道移動の映像を、反復する物体が個々の音へ同期するよう編集し、空間の反復と音楽の反復を同一のシステムへ統合しています。','Acquisition reason: Representative work for Rhythm Editing.','verified',now() from public.works where slug='chemical-brothers-star-guitar' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A train-window view converts passing buildings, poles, bridges, and platforms into visible counterparts of the track''s repeating musical layers.','The video demonstrates musical structure without diagrams or performance, making ordinary landscape function as a precise visual score.','Released in 2002 and directed by Michel Gondry, the work belongs chronologically to the 2000s even though the editorial source sheet groups it within the 1990s batch.','Footage of a rail journey is edited so recurring objects align with individual sounds, allowing spatial repetition and musical repetition to become the same system.','Acquisition reason: Representative work for Rhythm Editing.','verified',now() from public.works where slug='chemical-brothers-star-guitar' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
