insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Chris Martinが交通事故の後景から、その前の移動と関係へ逆行しながら、歌だけは前向きに聞こえるよう演じる作品。','逆再生を単独の視覚的な仕掛けではなく、物語情報と感情的な結果の両方を運ぶ構造として用いました。','Jamie Thravesが監督し2002年に公開。Coldplayのセカンドアルバム期を代表する映像となり、2004年GRAMMY Best Music Videoにノミネートされました。','逆回転撮影、逆向きに覚えた口の同期、遅れて明かされる出来事、自然ロケーションによって、戻りたいという歌の欲求と映像の物理方向を一致させています。','Acquisition reason: Representative work for Reverse.','verified',now() from public.works where slug='coldplay-the-scientist' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Chris Martin moves backward from the aftermath of a car crash toward the journey and relationship that preceded it while appearing to sing forward.','The video makes reverse motion carry both narrative information and emotional consequence rather than functioning as an isolated visual trick.','Directed by Jamie Thraves and released in 2002, the film accompanied Coldplay''s second album period and was nominated for the 2004 GRAMMY for Best Music Video.','Reverse photography, backward-learned lip synchronization, delayed revelation, and natural locations align the song''s desire to return with the film''s physical direction.','Acquisition reason: Representative work for Reverse.','verified',now() from public.works where slug='coldplay-the-scientist' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
