insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','オフィスで働く女性の一日を、アイソメ図、断面図、ラベル、システムマップ、数量化された流れの連続として再構成した作品。','情報グラフィックを完全な物語環境へ変え、分析的な記述によって日常の内部にある見えない仕組みを可視化しました。','H5が制作し2002年に公開。データ主導のモーションデザインを代表する作品となり、2003年D&ADでWood Pencilを受賞しました。','アイソメ投影、図式的なトランジション、製品ライフサイクル、ラベル付き人体、同期するチャートによって、すべての物体と行為を別の情報層へ展開しています。','Acquisition reason: Representative work for Infographics.','verified',now() from public.works where slug='royksopp-remind-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','An office worker''s day is reconstructed as a continuous field of isometric diagrams, cutaways, labels, systems maps, and quantified flows.','The video turned information graphics into a complete narrative environment, using analytical description to reveal the hidden systems inside an ordinary routine.','Created by H5 and released in 2002, the film became a reference point for data-led motion design and received a D&AD Wood Pencil in 2003.','Isometric projection, diagrammatic transitions, product lifecycles, labeled anatomy, and synchronized charts allow every object and action to open into another layer of information.','Acquisition reason: Representative work for Infographics.','verified',now() from public.works where slug='royksopp-remind-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
