insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','粗い赤、白、黒、黄の玩具ブロックによって、The White Stripesと演奏を高速なストップモーションとして再構築した作品。','バンドの厳格な視覚アイデンティティを物質的なアニメーションの仕組みへ移し、低い解像度そのものを速度と個性の源にしました。','Michel Gondryの監督により2002年にシングル映像として公開され、バンドのブレイクスルー映像となり、2003年D&ADでGraphite Pencilを受賞しました。','フレームごとのブロック置換、限定色、急激な縮尺変化、音に同期するカットによって、身近な組立玩具を圧縮された演奏映像へ変えています。','Acquisition reason: Representative work for LEGO Animation.','verified',now() from public.works where slug='the-white-stripes-fell-in-love-with-a-girl' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Rapid stop-motion animation rebuilds the White Stripes and their performance as coarse red, white, black, and yellow toy-brick forms.','The video translated the band''s strict visual identity into a material animation system whose low resolution became a source of speed and character.','Released as a single in 2002 and directed by Michel Gondry, the film became the White Stripes'' breakthrough video and received a D&AD Graphite Pencil in 2003.','Frame-by-frame brick replacement, limited color, abrupt changes of scale, and synchronized cuts turn a familiar construction toy into a compressed performance image.','Acquisition reason: Representative work for LEGO Animation.','verified',now() from public.works where slug='the-white-stripes-fell-in-love-with-a-girl' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
