insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Gorillazが暗い塔の内部で演奏し、閉ざされた群衆の外では風車の島が広い空を漂う作品。','描画キャラクター、CG環境、記録された演者を一つの継続する世界へ置くことで、バーチャルバンドを一貫したスクリーン上の存在として確立しました。','『Demon Days』の先行シングルとして2005年に公開され、Jamie HewlettとPete Candelandが監督し、GRAMMY Best Short Form Music Videoにノミネートされました。','二次元のキャラクターアニメーションとCG空間を、共通する照明、質感、カメラ移動、大気的な奥行きによって統合しています。','Acquisition reason: Representative work for Virtual Band.','verified',now() from public.works where slug='gorillaz-feel-good-inc' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Gorillaz perform inside a dark tower while a windmill island drifts through open sky beyond the building''s enclosed crowd.','The video consolidated the virtual band as a coherent screen presence, allowing drawn characters, CG environments, and recorded performers to occupy one continuing world.','Released in 2005 as the lead single from Demon Days, the film was directed by Jamie Hewlett and Pete Candeland and received a GRAMMY nomination for Best Short Form Music Video.','Two-dimensional character animation and computer-generated space are integrated through shared lighting, texture, camera movement, and atmospheric depth.','Acquisition reason: Representative work for Virtual Band.','verified',now() from public.works where slug='gorillaz-feel-good-inc' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
