insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','裸足の太鼓奏者が、増え続ける子どもたちの列をアイスランドの風景から崖へ導き、最後に全員が跳躍する作品。','風景、衣装、行進、一つの未解決の行為だけで完全な神話を構築し、飛翔と落下の境界を意図的に開いたままにしました。','Arni & Kinskiが監督し2005年に公開。Sigur Rósの『Takk…』期に制作され、公開直前にアイスランドで撮影されました。','計測された行進、自然の縮尺を保つ風景、抑制された時代的衣装、一度のクライマックスカットによって、楽曲の蓄積と集団移動の物語を一致させています。','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='sigur-ros-glosoli' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A barefoot drummer leads a growing procession of children across an Icelandic landscape toward a cliff and a final collective leap.','The film builds a complete myth from landscape, costume, procession, and one unresolved action, keeping the boundary between flight and fall deliberately open.','Directed by Arni & Kinski and released in 2005, the video accompanied Sigur Rós''s Takk… period and was shot in Iceland shortly before publication.','Measured procession, natural-scale landscape, restrained period styling, and a single climactic cut align the song''s accumulation with a narrative of collective movement.','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='sigur-ros-glosoli' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
