insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','孤独な騎手が、ガンマン、ロボット、武術、バンドの演奏が同居する未来西部劇の風景を進む、意図的に過剰なジャンルフィクション。','ジャンルの衝突そのものを一つの制作言語として扱い、短編映画の規模と演劇性を、バンド演奏の直接性と共存させました。','Joseph Kahnが監督し2006年に公開。Museの『Black Holes and Revelations』期を代表する映像となり、2007年D&ADでWood Pencilを受賞しました。','マカロニ・ウェスタンの演出、SFの小道具、武術アクション、無声映画の字幕、ホログラム状の演奏を、同一の架空世界を構成する要素として編集しています。','Acquisition reason: Representative work for Genre Mashup.','verified',now() from public.works where slug='muse-knights-of-cydonia' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A lone rider crosses a future-western landscape where gunfighters, robots, martial arts, and the band appear inside one deliberately excessive genre fiction.','The video treats genre collision as a complete production language, allowing the scale and theatricality of a short film to coexist with the direct address of a band performance.','Directed by Joseph Kahn and released in 2006, the work accompanied Muse''s Black Holes and Revelations period and received a D&AD Wood Pencil in 2007.','Spaghetti-western staging, science-fiction props, martial-arts action, silent-film intertitles, and holographic performance are edited as parts of the same coherent invented world.','Acquisition reason: Representative work for Genre Mashup.','verified',now() from public.works where slug='muse-knights-of-cydonia' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
