insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','OK Goの4人が8台のトレッドミルを横断し、正面の固定視点によるワンテイクで精密な振付を演じる作品。','小規模な制作、反復可能な身体的着想、オンライン流通の組み合わせが、放送型プロモーションに匹敵する観客を生み得ることを示しました。','2006年に公開され、バンドの映像上のブレイクスルーとなり、第49回GRAMMY AwardsのBest Music Videoを受賞しました。','固定カメラ、露出した装置、同期する振付、途切れない一回の撮影によって、タイミングと身体的リスクそのものを画面の仕組みにしています。','Acquisition reason: Representative work for One Take.','verified',now() from public.works where slug='ok-go-here-it-goes-again' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The four members of OK Go perform a precisely timed routine across eight treadmills in a single continuous frontal view.','The video demonstrated that a modest production, a repeatable physical premise, and online circulation could generate an audience on the scale of broadcast promotion.','Released in 2006, the treadmill performance became OK Go''s breakthrough visual work and won the 49th GRAMMY Award for Best Music Video.','A locked camera, visible apparatus, synchronized choreography, and one uninterrupted take make timing and physical risk the complete visual system.','Acquisition reason: Representative work for One Take.','verified',now() from public.works where slug='ok-go-here-it-goes-again' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
