insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','変形した顔と身体を持つ人物が、スクリーン、冷たい照明、断続的な色光に照らされた暗い室内世界に現れる作品。','照明と露出に心理的なアイデンティティを担わせ、説明的な物語なしに、少数の身体と部屋を不安定な存在へ変えました。','The Knifeの『Silent Shout』期である2006年に公開され、デュオが保ってきた匿名性を禁欲的な映像形式へ拡張しました。','低露出、UVを思わせる色、画面光、補綴的な変形、ほぼ静止した構図によって、見えにくさを能動的な構成素材として用いています。','Acquisition reason: Representative work for Lighting.','verified',now() from public.works where slug='the-knife-silent-shout' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Figures with altered faces and bodies appear in a dark domestic world illuminated by screens, cold lamps, and intermittent colored light.','The video makes lighting and exposure carry psychological identity, allowing a minimal set of bodies and rooms to feel unstable without explanatory narrative.','Released in 2006 during The Knife''s Silent Shout period, the work extended the duo''s controlled anonymity into an austere moving-image form.','Underexposure, UV-like color, screen light, prosthetic distortion, and near-static framing use limited visibility as an active compositional material.','Acquisition reason: Representative work for Lighting.','verified',now() from public.works where slug='the-knife-silent-shout' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
