insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Battlesが反射するリハーサル空間で演奏し、ゆっくりしたカメラ移動、反復する建築線、制御された照明によって部屋そのものが光学装置へ変わる作品。','アンサンブル演奏を空間システムとして扱い、演奏者、楽器、反射、カメラの物理的な関係を、個々の身振りと同じ重要度で見せました。','Warpから2007年に、同レーベルでのBattles初の新曲として公開され、『Mirrored』期の視覚言語を提示しました。','鏡面の壁、境界の明確なセット、横方向のカメラ移動、同期する照明、限定的なポスト処理によって、単純なバンド演奏を絶えず組み替わる図式へ変換しています。','Acquisition reason: Candidate representative work for Performance.','verified',now() from public.works where slug='battles-atlas' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Battles perform inside a reflective rehearsal enclosure while slow camera movement, repeated architectural lines, and controlled lighting turn the room into an optical instrument.','The video treats ensemble performance as a spatial system, making the physical relationships between musicians, instruments, reflections, and camera as important as individual gesture.','Released by Warp in 2007 as Battles'' first new music for the label, the work introduced the visual language associated with the Mirrored period.','Mirrored walls, a tightly bounded set, lateral camera movement, synchronized lighting, and selective post-production transform a straightforward band performance into a continuously reconfigured diagram.','Acquisition reason: Candidate representative work for Performance.','verified',now() from public.works where slug='battles-atlas' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
