insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Justiceが暗い空間を歩き、シャツ上のタイポグラフィ、歌詞、記号、身体、ポップイメージが絶えず置き換わる作品。','別の物語を説明するのではなく、グラフィックデザインそのものを主要な演者とし、レコードの視覚的アイデンティティを動く文字へ結びました。','Ed Banger Recordsから2007年に公開され、Justiceを代表する初期の視覚表現となり、2008年GRAMMY Best Music Videoにノミネートされました。','フレームごとに変化する衣服の図像、入れ子状の画像、手描き文字、連続する横移動によって、シャツ表面を編集可能な画面として機能させています。','Acquisition reason: Representative work for Typography.','verified',now() from public.works where slug='justice-d-a-n-c-e' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Justice walk through a dark environment while animated shirts continuously replace typography, lyrics, symbols, bodies, and pop images across their torsos.','The video made graphic design the principal performer, joining a record''s visual identity to moving typography rather than illustrating a separate narrative.','Released in 2007 on Ed Banger Records, the single introduced a prominent visual statement for Justice and was nominated for the 2008 GRAMMY for Best Music Video.','Frame-by-frame garment graphics, nested images, hand-drawn type, and continuous lateral movement make the shirt surface behave as an editable screen.','Acquisition reason: Representative work for Typography.','verified',now() from public.works where slug='justice-d-a-n-c-e' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
