insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Kanye Westが、研究施設、オートバイ、シャッターシェード、日本語の文字、SF的に構成された身体が交錯する高彩度の東京を移動する作品。','メインストリームのヒップホップを日本の都市文化とアニメの参照群へ接続し、文化的引用を新しいポップ人格の推進力として扱いました。','Hype Williamsが監督し、『Graduation』期の2007年に公開。Westが電子的な制作と大規模な視覚アイデンティティへ移行する時期と重なります。','ゲリラ的なロケ撮影、発光するグラフィック合成、高速なコンポジット、医療イメージ、『AKIRA』への明示的な参照によって、東京を人工的な演奏空間へ圧縮しています。','Acquisition reason: Representative work for Anime Influence.','verified',now() from public.works where slug='kanye-west-stronger' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Kanye West moves through a saturated Tokyo of laboratories, motorcycles, shutter shades, Japanese type, and bodies framed through science-fiction imagery.','The video joined mainstream hip-hop to a dense field of Japanese urban and anime references, treating cultural citation as the engine of a new pop persona.','Directed by Hype Williams and released in 2007 during the Graduation period, the work coincided with West''s shift toward electronic production and stadium-scale visual identity.','Guerrilla location footage, luminous graphic overlays, rapid compositing, medical imagery, and explicit echoes of Akira compress Tokyo into a synthetic performance space.','Acquisition reason: Representative work for Anime Influence.','verified',now() from public.works where slug='kanye-west-stronger' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
