insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','3人のダンサー、モノクロのスタジオ、精密に同期した振付で構成されたミニマルなパフォーマンス映像。','要素を削ぎ落とすことで、振付、シルエット、反復そのものを作品の視覚的アイデンティティにした代表例です。','Jake Navaが監督した2008年の作品で、振付を軸とするオンライン上の模倣と拡散の基準点になりました。','長いパフォーマンス区間と簡潔な白ホリゾントにより、身体の精度、フォーメーション、カメラのリズムへ視線を集中させています。','Acquisition reason: Representative work for Choreography.','verified',now() from public.works where slug='beyonce-single-ladies' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Three dancers, a monochrome studio, and tightly synchronized choreography define a deliberately minimal performance video.','The work demonstrates how reduction can strengthen an image: choreography, silhouette, and repetition become the complete visual identity.','Released in 2008 and directed by Jake Nava, the video became a major reference point for choreography-led online circulation and imitation.','Long performance passages and a minimal seamless set keep attention on bodily precision, formation, and camera rhythm.','Acquisition reason: Representative work for Choreography.','verified',now() from public.works where slug='beyonce-single-ladies' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
