insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','山口一郎が暗いスタジオを歩き、分解された歌詞のオブジェがカメラの視点と重なる瞬間に読める文字へ変わる作品。','タイポグラフィを画面上の合成ではなく物理的な出来事に変え、読む行為をカメラ移動、演奏、時間の経過へ接続しました。','関和亮が監督し2010年に公開。第14回文化庁メディア芸術祭エンターテインメント部門で優秀賞を受賞しました。','連続する移動撮影、強制遠近法の文字、フリップアニメーション、照明の合図、実物の舞台装置によって、デジタル合成を使わずに可視化された言葉と楽曲を同期しています。','Acquisition reason: Representative work for One Take.','verified',now() from public.works where slug='sakanaction-aruku-around' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Ichiro Yamaguchi walks through a dark studio while fragmented lyric objects align with the camera and become readable at precisely timed viewpoints.','The video makes typography a physical event rather than an overlay, joining the act of reading to camera movement, performance, and the passage of time.','Directed by Kazuaki Seki and released in 2010, the work received an Excellence Award in the Entertainment Division of the 14th Japan Media Arts Festival.','A continuous moving shot, forced-perspective letterforms, flip animation, lighting cues, and practical scenic mechanisms synchronize visible language with the song without digital compositing.','Acquisition reason: Representative work for One Take.','verified',now() from public.works where slug='sakanaction-aruku-around' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
