insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','改造されたChevrolet Sonicで砂漠のコースを走行しながら、道路沿いに配置された多数の調律済みオブジェクトと楽器を楽曲に同期して鳴らす作品。','自動車、道路、楽器群を一つの連続した演奏システムへ統合し、制作方法そのものを中心的な映像として可視化しました。','2012年のSuper Bowl放送に合わせて公開され、OK Goが継続してきた単一システム型のパフォーマンスを、特別改造車を中心とするブランド制作へ展開しました。','車体に取り付けたロボットアームで走路上の多数の音響要素を作動させ、走行速度、物理的衝突、音楽的タイミング、撮影を実空間で同期しています。','Acquisition reason: Candidate representative work for Practical Machine.','verified',now() from public.works where slug='ok-go-needing-getting' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','OK Go performs while a modified Chevrolet Sonic drives through a desert course, striking a large network of tuned objects and instruments in synchronization with the song.','The work turns an automobile, a road, and an instrument field into one continuous performance system, making the production method visible as the central image.','Released in 2012 around a Super Bowl broadcast, the project adapted OK Go''s established interest in single-system performances to a branded production built around a specially modified car.','Robotic arms attached to the vehicle activate hundreds of tuned elements along the route, coordinating driving speed, physical impact, musical timing, and camera coverage within a practical environment.','Acquisition reason: Candidate representative work for Practical Machine.','verified',now() from public.works where slug='ok-go-needing-getting' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
