insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','数百人の演者がロサンゼルスを移動するワンテイクの断片を、連続する24時間のインタラクティブな時間軸へ配置した作品。','MVを固定された短編から一日分の閲覧可能な構造へ拡張しながら、各断片を、一人の演者、一つの場所、一つの楽曲による直接的な出会いとして保ちました。','We Are From LAが監督し2013年に公開。24時間版は2014年D&ADで3本のPencilを獲得し、2015年GRAMMY Best Music Videoを受賞しました。','時計に基づくインターフェース、ループする楽曲構造、反復する追跡撮影、場所の連続性、大規模な出演者によって、継続時間そのものを作品の構成原理にしています。','Acquisition reason: Representative work for 24 Hours.','verified',now() from public.works where slug='pharrell-williams-happy' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Hundreds of performers move through Los Angeles in repeating single-take segments arranged across a continuous twenty-four-hour interactive timeline.','The project expanded a music video from a fixed short film into a day-long navigable structure, while keeping each segment legible as a direct encounter between one performer, one place, and one song.','Directed by We Are From LA and released in 2013, the 24-hour project received three D&AD Pencils in 2014 and the 2015 GRAMMY for Best Music Video.','A clock-based interface, looping song structure, repeated tracking shots, location continuity, and a large cast make duration itself the organizing principle of the work.','Acquisition reason: Representative work for 24 Hours.','verified',now() from public.works where slug='pharrell-williams-happy' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
