insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','葬儀の最中に二人の子どもが棺から起き上がり、大人たちには見えないまま教会を出て、街を踊りながら去っていく作品。','悲嘆と解放を同じ画面に置き、振付を楽曲の説明ではなく物語を進める行為として機能させました。','Hiro Muraiが監督し、Flying Lotusの『You''re Dead!』期である2014年に公開。2015年UK Music Video AwardsでBest Alternative Video — Internationalを受賞しました。','儀式的な静止から広がりのある動きへ連続的に移行し、説明的な台詞やVFXに頼らず、二人の若い演者が作品の感情変化を担います。','Acquisition reason: Representative work for Dance.','verified',now() from public.works where slug='flying-lotus-never-catch-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Two children rise from their coffins during a funeral and dance out of the church, through the streets, and away from the mourning adults who cannot see them.','The video uses dance to hold grief and release in the same image, allowing choreography to function as narrative action rather than illustration.','Directed by Hiro Murai and released in 2014 during Flying Lotus''s You''re Dead! period, the film won Best Alternative Video — International at the 2015 UK Music Video Awards.','A continuous progression from ritual stillness to expansive movement lets two young performers carry the film''s emotional shift without explanatory dialogue or visual effects.','Acquisition reason: Representative work for Dance.','verified',now() from public.works where slug='flying-lotus-never-catch-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
