insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Maddie Zieglerが荒れた室内で持続的なソロを演じ、遊び、衝動、疲労、対峙のあいだを身体で移動する作品。','一人のダンサーをポップ作品の中心に置き、歌手本人の身体的な登場ではなく、振付によって作品の公共的イメージを定義しました。','SiaとDaniel Askillが監督し2014年に公開。UKMVAのBest Pop Video — International、D&ADの2本のPencilを獲得し、2015年GRAMMY Best Music Videoにノミネートされました。','境界のある室内セット、近接するカメラ、伸縮性の高い全身振付、一貫した演技上の人格によって、動きそのものを映像の完全な物語語彙にしています。','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='sia-chandelier' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Maddie Ziegler performs a sustained solo inside a neglected apartment, moving between play, compulsion, exhaustion, and confrontation.','The video places a single dancer at the center of a pop release and allows choreography, rather than the singer''s physical presence, to define the work''s public image.','Directed by Sia and Daniel Askill and released in 2014, the video won Best Pop Video — International at the UKMVAs, received two D&AD Pencils, and was nominated for the 2015 GRAMMY for Best Music Video.','A bounded domestic set, close camera proximity, elastic full-body choreography, and an uninterrupted performance identity turn movement into the video''s complete narrative vocabulary.','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='sia-chandelier' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
