insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','無関心なナイトクラブの観客を前にThe Weekndが歌い、投げ込まれたライターで身体に火がついた瞬間、会場の注意が反転する作品。','通常のステージ・パフォーマンスを、露出、危険、公共的承認の簡潔なイメージへ転換し、一つの実写効果で場面全体の意味を組み替えました。','『Beauty Behind the Madness』期の2015年に公開され、Grant Singerが監督し、Anonymous Contentを通じて制作されました。','抑制されたクラブの設定で中心的な効果を終盤まで遅らせ、炎、観客の反応、継続する演技によって無関心をスペクタクルへ変換しています。','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='the-weeknd-cant-feel-my-face' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The Weeknd performs to a disengaged nightclub audience until a thrown lighter sets him on fire and the room''s attention abruptly reverses.','The video turns a conventional stage performance into a concise image of exposure, danger, and public approval, using one practical event to reorganize the entire scene.','Released in 2015 during the Beauty Behind the Madness period, the video was directed by Grant Singer and produced through Anonymous Content.','A restrained club setup delays its central effect until the final section, allowing fire, crowd reaction, and continuous performance to convert indifference into spectacle.','Acquisition reason: Representative work for Performance.','verified',now() from public.works where slug='the-weeknd-cant-feel-my-face' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
