insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Thom Yorkeが扉を通り抜け、住宅、職場、施設、街路、最後の雪山へ連続して移動する作品。','日常的な境界を用いて論理的には共存しない空間を接続し、感情的な離脱を途切れない身体移動へ翻訳しました。','『A Moon Shaped Pool』に先行して2016年5月に公開され、Paul Thomas Andersonが監督。Radioheadにとって5年ぶりとなるスタジオ・アルバムの再始動を伴いました。','一致した歩行と扉のトランジションで多数のロケーションを一続きに見せ、編集を目立つ中断ではなく建築的な接続として機能させています。','Acquisition reason: Candidate representative work for Narrative.','verified',now() from public.works where slug='radiohead-daydreaming' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Thom Yorke walks through a chain of doors connecting homes, workplaces, institutional rooms, streets, and a final snowbound landscape.','The video translates emotional dislocation into continuous physical movement, using ordinary thresholds to connect spaces that cannot logically coexist.','Released in May 2016 ahead of A Moon Shaped Pool, Daydreaming was directed by Paul Thomas Anderson and accompanied Radiohead''s return after a five-year studio-album interval.','Matched movement and doorway transitions create an apparently continuous passage across many locations, making editing operate as architecture rather than visible interruption.','Acquisition reason: Candidate representative work for Narrative.','verified',now() from public.works where slug='radiohead-daydreaming' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
