insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','無人の工業空間で踊る身体が、透明な格子状のデジタル構造へ段階的に置き換わっていく作品。','途切れない振付の中で身体変容を明瞭に読み取らせ、パフォーマンスとVFXに同等の物語的役割を与えました。','2016年に公開され、Dom & Nicが監督、Outsiderが制作、The Mill LondonがVFXを担当し、Virgin EMIから発表されました。','精密なトラッキング、デジタル身体置換、連続して見えるカメラ動線によって、ダンサーの動きを保ちながら合成された内部構造を段階的に露出させています。','Acquisition reason: Candidate representative work for Body Transformation.','verified',now() from public.works where slug='chemical-brothers-wide-open' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A dancer moves through an empty industrial space while her body is progressively replaced by a transparent, lattice-like digital structure.','The video makes bodily transformation readable through uninterrupted choreography, allowing performance and visual effects to carry equal narrative weight.','Released in 2016, Wide Open was directed by Dom & Nic, produced by Outsider, and completed with visual effects by The Mill London for Virgin EMI.','Detailed tracking, digital body replacement, and a continuous-feeling camera path preserve the dancer''s movement while gradually exposing a synthetic internal structure.','Acquisition reason: Candidate representative work for Body Transformation.','verified',now() from public.works where slug='chemical-brothers-wide-open' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
