insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','人物が同じように見える複数の部屋を進むたびに空間が段階的に縮小し、日常的な室内を精密な知覚の錯覚へ変える作品。','プロダクションデザインそのものに錯覚の中心を担わせ、説明的な物語に依存せず、スケール変化だけで不穏な移動体験を作りました。','Oscar HudsonがBonoboとNick Murphyのために監督した2017年の作品で、UK Music Video AwardsのBest UK Dance VideoとBest Production Design in a Videoを受賞しました。','段階的に縮小した実物セット、スケールの異なる小道具、対応する構図、振り付けられた移動を組み合わせ、物理的な手触りを保ったまま連続的な縮小効果を成立させています。','Acquisition reason: Candidate representative work for Narrative.','verified',now() from public.works where slug='bonobo-no-reason' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A performer moves through a sequence of apparently identical rooms that become progressively smaller, turning domestic space into a controlled perceptual distortion.','The film makes production design carry the central illusion, demonstrating how changes of scale can create an uncanny journey without relying on an explanatory narrative.','Oscar Hudson directed the 2017 video for Bonobo and Nick Murphy. It received the UK Music Video Awards for Best UK Dance Video and Best Production Design in a Video.','Successive physical rooms, scaled props, matched framing, and choreographed movement create a continuous shrinking effect while preserving the tactile evidence of real sets.','Acquisition reason: Candidate representative work for Narrative.','verified',now() from public.works where slug='bonobo-no-reason' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
