insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','同期制御されたプリンターの壁の前でバンドが演奏し、排出される紙が色、模様、文字、擬似的な奥行きを高速に作り替える作品。','事務機器、振付、ソフトウェア制御、印刷された紙を等しく可視化し、技術システムそのものを理解可能なライブ・パフォーマンス環境へ変えました。','2017年に公開され、田中裕介とDamian Kulash Jr.が監督、AOI Pro.が制作。2018年Webby AwardsのMusic Video部門でPeople''s Voiceを受賞しました。','多数のプリンターをプログラム可能な画像面として同期し、カメラ移動、バンドの配置、紙の出力を実空間で精密に合わせています。','Acquisition reason: Candidate representative work for Optical Illusion.','verified',now() from public.works where slug='ok-go-obsession' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The band performs in front of a wall of synchronized printers whose sheets form rapidly changing fields of colour, pattern, text, and simulated depth.','The work makes office hardware, choreography, software control, and printed paper equally visible, turning a technical system into a legible live performance environment.','Released in 2017, Obsession was directed by Yusuke Tanaka and Damian Kulash Jr., produced by AOI Pro., and received the 2018 Webby People''s Voice award for Music Video.','Hundreds of printers are synchronized as a programmable image surface while camera movement, band blocking, and paper output are coordinated in physical space.','Acquisition reason: Candidate representative work for Optical Illusion.','verified',now() from public.works where slug='ok-go-obsession' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
