insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','移動するカメラが倉庫内のChildish Gambinoを追い、演技、祝祭、銃による暴力、混乱が前景と背景で注意を奪い合う作品。','スペクタクルの仕組みそのものを使って、米国における気晴らし、暴力、人種、娯楽を考察し、観客の移ろう注意を作品の一部にしました。','Hiro Muraiが監督し2018年に公開。直ちに広範な解釈の対象となり、2019年GRAMMY Best Music Videoを受賞しました。','長い移動撮影の中で、前景の振付と画面奥の事件を同時進行させ、中心の演技と周囲の証拠のどちらを見るかを観客に選ばせます。','Acquisition reason: Representative work for Social Commentary.','verified',now() from public.works where slug='childish-gambino-this-is-america' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A mobile camera follows Childish Gambino through a warehouse as performance, celebration, gun violence, and disorder compete across foreground and background.','The video uses the mechanics of spectacle to examine distraction, violence, race, and entertainment in the United States, making the viewer''s shifting attention part of the work.','Directed by Hiro Murai and released in 2018, the video became an immediate subject of public interpretation and received the 2019 GRAMMY for Best Music Video.','Long moving passages coordinate foreground choreography with incidents placed deep in the frame, forcing the viewer to choose between the central performance and the surrounding evidence.','Acquisition reason: Representative work for Social Commentary.','verified',now() from public.works where slug='childish-gambino-this-is-america' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
