insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','教会で歌う米津玄師と葬送を思わせる集いを、象徴的な物、抑制された演技、不穏な室内の空気とともに描いた作品。','象徴的な小道具、建築、抑制されたパフォーマンス、統御された曖昧さによって、広く共有された悲嘆の歌を持続的な映像へ変換しました。','テレビドラマ『アンナチュラル』の主題歌として2018年に公開され、山田智和が監督。MTV VMAJ 2018で2部門を受賞しました。','節度あるカメラ移動、振付化された身振り、反復する象徴物、彩度を抑えた美術設計によって、喪失を簡潔な視覚体系へ置き換えています。','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='kenshi-yonezu-lemon' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A restrained cinematic portrait combines Kenshi Yonezu''s performance in a church with a funeral-like gathering, symbolic objects, and an uncanny interior atmosphere.','The video shows how symbolic props, architecture, restrained performance, and controlled ambiguity can sustain a widely shared song of grief.','Released in 2018 as the theme for the television drama Unnatural, the video was directed by Tomokazu Yamada and won two awards at the 2018 MTV VMAJ.','Measured camera movement, choreographed gesture, recurring symbolic objects, and muted production design translate mourning into a spare visual system.','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='kenshi-yonezu-lemon' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
