insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','高密度な3DCG都市、飛行車両、仮面の人物、インターフェース・グラフィック、モーションキャプチャの演技が連続するサイバーパンクの追跡劇。','日本のクリエイティブ・コレクティブが、アニメーション、CG、グラフィック、コンポジット、パフォーマンスキャプチャを一つの作家システムとして統括できることを示しました。','『攻殻機動隊 SAC_2045』との接続を持つ2020年の作品で、PERIMETRONの佐々木集と神戸雄平が監督し、多数の専門チームが参加しました。','複数の専門スタジオと視覚言語を統一されたリアルタイム感のある世界へ結合し、モーションキャプチャとUI表現によってデジタルキャラクターへ演技の存在感を与えています。','Acquisition reason: Candidate representative work for Experimental / Mixed Media.','verified',now() from public.works where slug='millennium-parade-fly-with-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A dense 3DCG city, airborne vehicles, masked figures, interface graphics, and motion-captured performance form a continuous cyberpunk pursuit.','The work demonstrates how a Japanese creative collective can coordinate animation, CG, graphic design, compositing, and performance capture as one authorship system.','Released in 2020 in connection with Ghost in the Shell: SAC_2045, the video was directed within PERIMETRON by Shu Sasaki and Yuhei Kanbe with a large distributed production team.','Multiple specialist studios and visual languages are combined inside a unified realtime-feeling world, with motion capture and graphic interfaces giving digital characters a performative presence.','Acquisition reason: Candidate representative work for Experimental / Mixed Media.','verified',now() from public.works where slug='millennium-parade-fly-with-me' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
