insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','The Weekndがストロボに照らされた地下クラブへ入り、ダンス、呼吸、官能的な危険、機械的拘束が制御された工業空間で展開する作品。','楽曲の身体的切迫を、点滅する光、制限された呼吸、圧力下のパフォーマンスから成る映像システムへ翻訳しました。','『Dawn FM』期の始まりとなる2021年に公開され、Cliquaが監督、Somesuchが制作。2021年UK Music Video AwardsのShortlistに選出されました。','照明のリズム、煙霧、身体の接近、制御されたカメラ移動を結び、クラブ・パフォーマンスと自発的な危険の物語を融合しています。','Acquisition reason: Representative work for Lighting.','verified',now() from public.works where slug='the-weeknd-take-my-breath' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','The Weeknd enters a strobe-lit underground club where dance, breath, erotic danger, and mechanical restraint unfold within a tightly controlled industrial environment.','The video translates the song''s physical urgency into an image system built from flashing light, restricted breath, and performance under pressure.','Released in 2021 at the beginning of the Dawn FM cycle, the video was directed by Cliqua and produced by Somesuch; it was shortlisted at the 2021 UK Music Video Awards.','Lighting rhythm, haze, close physical contact, and controlled camera movement fuse nightclub performance with a narrative of voluntary risk.','Acquisition reason: Representative work for Lighting.','verified',now() from public.works where slug='the-weeknd-take-my-breath' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
