insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Tyler, The Creatorが旅行、高級品、人工的な天候、急なスケールと場所の変化を含む小型の舞台セットを移動する作品。','短い尺の中に完全な視覚的人格を圧縮し、美術と喜劇的な中断によって『Call Me If You Get Lost』の世界を高い密度で導入しました。','『Call Me If You Get Lost』に先行して2021年に公開され、Tyler Okonmaが継続して用いるWolf Haley名義の演出体系に位置づきます。','ハードカット、ミニチュアのようなセット、正面性の強い人物配置、意図的に人工的な天候によって、歌詞の断片を独立した舞台イメージへ変えています。','Acquisition reason: Representative work for Art Direction.','verified',now() from public.works where slug='tyler-the-creator-lumberjack' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Tyler, The Creator moves through compact theatrical sets involving travel, luxury objects, forced weather, and abrupt changes of scale and location.','The video compresses a complete visual persona into a short duration, using production design and comic interruption to introduce the Call Me If You Get Lost world with unusual economy.','Released in 2021 before Call Me If You Get Lost, the work was directed under Tyler Okonma''s established Wolf Haley authorship.','Hard cuts, miniature-feeling sets, frontal blocking, and deliberately artificial weather turn each lyric fragment into a self-contained stage image.','Acquisition reason: Representative work for Art Direction.','verified',now() from public.works where slug='tyler-the-creator-lumberjack' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
