insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','室内、街路、交通機関、水辺で撮影された親密な手持ち映像の中に宇多田ヒカルが現れ、撮る行為自体も画面へ残される作品。','大規模映画主題歌に磨き込まれたフランチャイズ映像ではなく個人的な観察を与え、非公式な映像日記の尺度と質感へ置き換えました。','『シン・エヴァンゲリオン劇場版』の主題歌として2021年に公開され、庵野秀明が監督。遠隔で撮影された素材を用いて構成されました。','民生機に近いカメラ、撮影動作の可視化、異なる画質を一つの肖像へ編集し、距離と媒介された親密さを形式の一部にしています。','Acquisition reason: Representative work for Minimalism.','verified',now() from public.works where slug='hikaru-utada-one-last-kiss' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Hikaru Utada appears in intimate handheld images gathered across domestic rooms, streets, transport, and waterfront locations, with the act of recording left visible.','The work replaces polished franchise imagery with personal observation, giving a major film theme the scale and texture of an informal visual diary.','Released in 2021 as the theme for Evangelion: 3.0+1.0 Thrice Upon a Time, the video was directed by Hideaki Anno and assembled from remotely captured footage.','Consumer-scale cameras, visible filming gestures, and multiple image qualities are edited into a coherent portrait that makes distance and mediated intimacy part of the form.','Acquisition reason: Representative work for Minimalism.','verified',now() from public.works where slug='hikaru-utada-one-last-kiss' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
