insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Kendrick Lamarとセラピストの対話から、演出された記憶、告発、群像、対立と解放のイメージへ展開する作品。','内省と自己尋問を物語の駆動力とし、MV形式を用いて私的な発話と象徴的な公共場面を往復しました。','『Mr. Morale & the Big Steppers』期の2022年に公開され、Dave FreeとKendrick Lamarが監督。2024年GRAMMY AwardsのBest Music Videoにノミネートされました。','抑制された対話の枠から精密に構成された小場面へ拡張し、セラピー、記憶、パフォーマンス、寓意を単一の時間順へ解消せず接続しています。','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='kendrick-lamar-count-me-out' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','A therapy session between Kendrick Lamar and a clinician opens into staged memories, accusations, group tableaux, and images of conflict and release.','The work makes reflection and self-interrogation its narrative engine, using the music-video form to move between private speech and symbolic public scenes.','Released in 2022 during the Mr. Morale & the Big Steppers period, the video was directed by Dave Free and Kendrick Lamar and later nominated for the 2024 GRAMMY Award for Best Music Video.','A sparse conversational frame expands into precisely composed vignettes, allowing transitions between therapy, memory, performance, and allegory without resolving them into a single chronology.','Acquisition reason: Representative work for Narrative.','verified',now() from public.works where slug='kendrick-lamar-count-me-out' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
