insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Side AとSide Bの連作で、一人の女子生徒がNewJeansと同級生を撮影し、記憶、ファンダム、カメラの信頼性が徐々に分離していく作品。','アイドル映像を直接的な宣伝ではなく記憶された証拠として扱い、ファン、演者、記録映像の不安定な関係の中へ鑑賞者を置きました。','2022年12月に公開され、Shin Woo-seokが監督、Dolphiners Filmsが制作。NewJeansとADORのための二部構成の物語として発表されました。','民生映像の質感、視点を変えて反復される場面、二本の映画構造によって、記録行為そのものを存在が不在へ変わる仕組みにしています。','Acquisition reason: Representative work for Youth Narrative.','verified',now() from public.works where slug='newjeans-ditto' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Presented across linked Side A and Side B films, a schoolgirl records NewJeans and her classmates while memory, fandom, and the reliability of the camera gradually separate.','The work treats idol imagery as remembered evidence rather than direct promotion, placing the viewer inside an unstable relationship between fan, performer, and recorded image.','Released in December 2022, Ditto was directed by Shin Woo-seok and produced by Dolphiners Films as a two-part narrative for NewJeans and ADOR.','Consumer-video texture, repeated scenes from altered viewpoints, and a two-film structure make recording itself the mechanism through which presence becomes absence.','Acquisition reason: Representative work for Youth Narrative.','verified',now() from public.works where slug='newjeans-ditto' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
