insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'ja','Doja Cat自身の絵画を基にしたシュルレアルな場面を移動し、死の人物、露出した肉体、悪魔、不可能な生物が現れる作品。','アーティストの準備絵画を大規模ポップ制作の支配的な構造にし、そのグロテスクな図像を保ったままパフォーマンス空間へ拡張しました。','KemosabeとRCAから2023年に公開され、Doja CatとNina McNeelyが共同監督、Freenjoyが制作しました。','三つの絵画構図を立体セットとVFXシークエンスとして再構築し、色、クリーチャー造形、振付、編集を静止した原画と実写の間で往復させています。','Acquisition reason: Representative work for VFX.','verified',now() from public.works where slug='doja-cat-paint-the-town-red' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
insert into public.work_editorials (work_id,locale,short_summary,why_it_matters,historical_context,key_innovation,editorial_notes,verification_status,reviewed_at) select id,'en','Doja Cat moves through a sequence of surreal tableaux derived from her own paintings, accompanied by death figures, exposed flesh, devils, and impossible creatures.','The video makes an artist''s preparatory paintings the governing structure of a major pop production, preserving their grotesque imagery while expanding them into performance space.','Released in 2023 through Kemosabe and RCA, the video was co-directed by Doja Cat and Nina McNeely and produced by Freenjoy.','Three painted compositions are reconstructed as dimensional sets and effects sequences, allowing colour, creature design, choreography, and editing to move between static source image and live action.','Acquisition reason: Representative work for VFX.','verified',now() from public.works where slug='doja-cat-paint-the-town-red' on conflict (work_id,locale) do update set short_summary=excluded.short_summary,why_it_matters=excluded.why_it_matters,historical_context=excluded.historical_context,key_innovation=excluded.key_innovation,editorial_notes=excluded.editorial_notes,verification_status='verified',reviewed_at=excluded.reviewed_at;
